def canStamp(stamp, target):
    m, n = len(stamp), len(target)
    todo = []
    made = []
    queue = []
    for i in range(n - m + 1):
        ok = []
        bad = set()
        for j in range(m):
            if target[i + j] == stamp[j]:
                ok.append(i + j)
            else:
                bad.add(i + j)
        made.append(ok)
        todo.append(bad)
        if not bad:
            queue.append(i)
    erased = [False] * n
    count = 0
    while queue:
        i = queue.pop()
        for pos in made[i]:
            if not erased[pos]:
                erased[pos] = True
                count += 1
                for w in range(max(0, pos - m + 1), min(pos, n - m) + 1):
                    if pos in todo[w]:
                        todo[w].discard(pos)
                        if not todo[w]:
                            queue.append(w)
    return count == n
